import type { BankQuestion } from "@/lib/bank";

/** Ray and Wave Optics (Physics (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-optics-1","question":"The radius of curvature of a concave mirror is 20 cm. Its focal length is:","options":["40 cm","20 cm","10 cm","5 cm"],"answer":2,"explanation":"For a spherical mirror f = R/2 = 20/2 = 10 cm (negative in the sign convention for a concave mirror).","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-optics-2","question":"The refractive index of a medium with respect to air is 2. The critical angle for the medium–air interface is:","options":["60°","45°","30°","90°"],"answer":2,"explanation":"sin C = 1/n = 1/2, so C = 30°. Light inside the medium striking the surface at more than 30° is totally internally reflected.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-optics-3","question":"The speed of light in glass of refractive index 1.5 is (c = 3 × 10⁸ m/s):","options":["4.5 × 10⁸ m/s","3 × 10⁸ m/s","2 × 10⁸ m/s","1.5 × 10⁸ m/s"],"answer":2,"explanation":"n = c/v, so v = c/n = 3 × 10⁸/1.5 = 2 × 10⁸ m/s. The frequency is unchanged; the wavelength falls by the factor 1.5.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-optics-4","question":"An object is placed at a distance 2f from a convex lens of focal length f. The image formed is:","options":["Real, inverted, same size, at 2f on the other side","Real, inverted, magnified, beyond 2f","Virtual, erect, magnified, on the same side","Real, inverted, diminished, between f and 2f"],"answer":0,"explanation":"1/v − 1/(−2f) = 1/f gives v = 2f, and m = v/u = −1: a real, inverted image of the same size at 2f on the other side.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-optics-5","question":"The power of a concave lens of focal length 25 cm is:","options":["+4 D","−4 D","−0.04 D","+0.25 D"],"answer":1,"explanation":"P = 1/f with f in metres: f = −0.25 m, so P = −4 D. Dioptre values need the focal length in metres, and a concave (diverging) lens has negative power.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-optics-6","question":"Two thin lenses of powers +5 D and −2 D are placed in contact. The focal length of the combination is:","options":["+33.3 cm","+14.3 cm","−33.3 cm","+50 cm"],"answer":0,"explanation":"Powers of lenses in contact add: P = 5 − 2 = +3 D, so f = 1/3 m ≈ +33.3 cm, a converging combination.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-optics-7","question":"In Young's double-slit experiment the slits are 1 mm apart and the screen is 1 m away. For light of wavelength 600 nm the fringe width is:","options":["0.6 mm","6 mm","0.06 mm","1.2 mm"],"answer":0,"explanation":"β = λD/d = 600 × 10⁻⁹ × 1 / 10⁻³ = 6 × 10⁻⁴ m = 0.6 mm.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-optics-8","question":"A prism of refracting angle 60° produces a minimum deviation of 30°. The refractive index of its material is:","options":["1.5","√2","√3","2"],"answer":1,"explanation":"n = sin((A + δ_min)/2) / sin(A/2) = sin 45°/sin 30° = (1/√2)/(1/2) = √2 ≈ 1.414.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-optics-9","question":"Light is incident from air on a transparent medium of refractive index √3. The angle of incidence at which the reflected light is completely plane-polarised is:","options":["30°","45°","60°","90°"],"answer":2,"explanation":"Brewster's law: tan i_p = n = √3, so i_p = 60°. At this angle the reflected and refracted rays are perpendicular to each other.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-optics-10","question":"An object is placed 15 cm in front of a concave mirror of focal length 10 cm. The image is:","options":["30 cm in front of the mirror, real, magnification −2","30 cm behind the mirror, virtual, magnification +2","6 cm in front of the mirror, real, magnification −0.4","15 cm in front of the mirror, real, magnification −1"],"answer":0,"explanation":"With u = −15 cm and f = −10 cm: 1/v = 1/f − 1/u = −1/10 + 1/15 = −1/30, so v = −30 cm (real, in front). m = −v/u = −(−30)/(−15) = −2: inverted and twice the size.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-11","question":"A tank contains water (n = 4/3) to a depth of 8 cm, and a glass slab (n = 1.5) 6 cm thick is placed on top of the water, covering it completely. Viewed normally from above, the apparent depth of the bottom of the tank is:","options":["14 cm","10 cm","9.3 cm","12 cm"],"answer":1,"explanation":"Apparent depth adds layer by layer: t₁/n₁ + t₂/n₂ = 6/1.5 + 8/(4/3) = 4 + 6 = 10 cm, against a real depth of 14 cm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-12","question":"A thin convex lens of glass (n = 1.5) has focal length 20 cm in air. Its focal length when immersed in water (n = 4/3) is:","options":["20 cm","40 cm","80 cm","−80 cm"],"answer":2,"explanation":"From the lens-maker's formula, f_water/f_air = (n_g − 1)/(n_g/n_w − 1) = 0.5/(1.125 − 1) = 0.5/0.125 = 4. So f_water = 4 × 20 = 80 cm; the lens stays converging but becomes weaker.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-13","question":"An astronomical telescope has an objective of focal length 100 cm and an eyepiece of focal length 5 cm. In normal adjustment (final image at infinity), its magnifying power and tube length are:","options":["20, 95 cm","20, 105 cm","0.05, 105 cm","500, 105 cm"],"answer":1,"explanation":"In normal adjustment M = f_o/f_e = 100/5 = 20 and the length L = f_o + f_e = 105 cm. The objective's large focal length gives magnification; the eyepiece must be short.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-14","question":"In Young's double-slit experiment, the intensity at the centre of a bright fringe is I₀. The intensity at a point where the path difference between the two waves is λ/4 is:","options":["I₀/4","Zero","3I₀/4","I₀/2"],"answer":3,"explanation":"A path difference of λ/4 gives a phase difference φ = (2π/λ)(λ/4) = π/2. I = I₀ cos²(φ/2) = I₀ cos²(45°) = I₀/2. Zero intensity needs a path difference of λ/2.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-15","question":"Light of wavelength 500 nm falls normally on a single slit of width 0.2 mm, and the diffraction pattern is observed on a screen 1 m away. The width of the central maximum is:","options":["2.5 mm","10 mm","1.25 mm","5 mm"],"answer":3,"explanation":"The first minima are at y = ±λD/a, so the central maximum has width 2λD/a = 2 × 500 × 10⁻⁹ × 1 / (0.2 × 10⁻³) = 5 × 10⁻³ m = 5 mm, twice the width of any secondary maximum.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-16","question":"A ray enters a right-angled isosceles prism (angles 45°, 45°, 90°) normally through one of the shorter faces and strikes the hypotenuse. The minimum refractive index of the prism for the ray to be totally internally reflected at the hypotenuse is:","options":["1.33","2","√3","√2"],"answer":3,"explanation":"The ray meets the hypotenuse at 45°. Total internal reflection needs 45° ≥ C, i.e. sin 45° ≥ 1/n, so n ≥ √2 ≈ 1.41. Ordinary glass (1.5) qualifies, which is why such prisms are used in periscopes and binoculars.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-17","question":"A thin prism of angle 5° is made of glass with refractive indices 1.52 for violet and 1.50 for red light. The angular dispersion between violet and red produced by the prism is:","options":["2.6°","0.2°","2.5°","0.1°"],"answer":3,"explanation":"For a thin prism δ = (n − 1)A, so the angular dispersion = (n_v − n_r)A = (1.52 − 1.50) × 5° = 0.1°. The mean deviation is about (1.51 − 1) × 5° = 2.55°.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-18","question":"An object is placed 20 cm in front of a convex mirror of focal length 20 cm. The image is:","options":["At infinity","20 cm behind the mirror, virtual, erect, same size","10 cm in front of the mirror, real, inverted, half the size","10 cm behind the mirror, virtual, erect, half the size"],"answer":3,"explanation":"With u = −20 cm, f = +20 cm: 1/v = 1/f − 1/u = 1/20 + 1/20 = 1/10, so v = +10 cm (behind the mirror). m = −v/u = −10/(−20) = +0.5: virtual, erect, half size. A convex mirror always forms a diminished virtual image.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-19","question":"How many of the following statements about wave optics are correct? (A) In Young's double-slit experiment with white light the central fringe is white. (B) If the whole double-slit apparatus is immersed in water the fringe width increases. (C) The phenomenon of polarisation shows that light waves are transverse. (D) Diffraction of sound around obstacles is observed more easily than diffraction of light because sound has a much larger wavelength.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (C) and (D) are correct. (B) is wrong: in water the wavelength becomes λ/n, so the fringe width β = λD/d decreases by the factor n.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-20","question":"A convex lens of focal length 20 cm and a concave lens of focal length 10 cm are placed coaxially 50 cm apart. An object is placed 30 cm in front of the convex lens. The final image is formed:","options":["10 cm beyond the concave lens","5 cm beyond the concave lens","At infinity","20 cm in front of the concave lens"],"answer":2,"explanation":"Convex lens: 1/v = 1/20 − 1/30 = 1/60, so v = 60 cm, i.e. 10 cm beyond the concave lens, which is 50 cm away. This acts as a virtual object (u = +10 cm) for the concave lens: 1/v = 1/(−10) + 1/10 = 0, so v = ∞. The rays converging towards the focus of the concave lens emerge parallel.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-21","question":"A plano-convex lens (n = 1.5) has a curved surface of radius 20 cm. Its plane surface is silvered. The combination behaves like a:","options":["Concave mirror of focal length 20 cm","Concave mirror of focal length 40 cm","Concave mirror of focal length 10 cm","Convex mirror of focal length 20 cm"],"answer":0,"explanation":"Lens focal length f_l = R/(n − 1) = 20/0.5 = 40 cm. Light passes through the lens, reflects from the plane mirror (power zero) and passes through the lens again: 1/F = 2/f_l + 1/f_m = 2/40 + 0 = 1/20 cm⁻¹, so the system is a converging (concave) mirror of focal length 20 cm, i.e. f_l/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-22","question":"A ray of light falls normally on one refracting face of a prism of angle 30° and refractive index √2. The deviation suffered by the ray on emerging from the other face is:","options":["15°","30°","45°","60°"],"answer":0,"explanation":"Normal incidence means r₁ = 0, so r₂ = A − r₁ = 30°. At the second face sin e = n sin r₂ = √2 × ½ = 1/√2, so e = 45°. Deviation δ = i + e − A = 0 + 45° − 30° = 15°.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-23","question":"In Young's double-slit experiment with light of wavelength 600 nm, a thin transparent sheet of refractive index 1.5 and thickness 6 μm is placed in front of one slit. The number of fringes by which the pattern shifts is:","options":["3","15","10","5"],"answer":3,"explanation":"The sheet adds an optical path (n − 1)t = 0.5 × 6 μm = 3 μm. Number of fringes shifted = (n − 1)t/λ = 3 × 10⁻⁶ / 6 × 10⁻⁷ = 5, towards the side of the covered slit. The fringe width itself is unchanged.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-24","question":"Assertion (A): A cut diamond sparkles brilliantly because of total internal reflection. Reason (R): The refractive index of diamond is about 2.42, so its critical angle is only about 24°.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"sin C = 1/2.42 gives C ≈ 24.4°. Such a small critical angle means light entering a suitably cut diamond is reflected internally many times before leaving, producing the sparkle. R correctly explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-optics-25","question":"Match the defect of vision (List I) with the corrective lens (List II). List I: (P) myopia; (Q) hypermetropia; (R) presbyopia; (S) astigmatism. List II: (1) convex lens; (2) cylindrical lens; (3) concave lens; (4) bifocal lens.","options":["P-1, Q-3, R-4, S-2","P-3, Q-1, R-4, S-2","P-3, Q-1, R-2, S-4","P-3, Q-4, R-1, S-2"],"answer":1,"explanation":"A myopic eye focuses distant objects in front of the retina, so a diverging (concave) lens is used; hypermetropia needs a converging lens; presbyopia (loss of accommodation with age) is corrected by bifocals; astigmatism, due to unequal curvature, by a cylindrical lens.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-optics-26","question":"A simple microscope (magnifying glass) has a focal length of 5 cm. For a person with least distance of distinct vision 25 cm, the magnifying power when the image is formed at the near point is:","options":["5","6","4","25"],"answer":1,"explanation":"With the image at the near point, M = 1 + D/f = 1 + 25/5 = 6. If the image is formed at infinity (relaxed eye), M = D/f = 5.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-optics-27","question":"In a double-slit experiment the widths of the two slits are in the ratio 4 : 1, so the intensities of light from them are in the ratio 4 : 1. The ratio of the maximum to the minimum intensity in the interference pattern is:","options":["4 : 1","9 : 1","3 : 1","16 : 1"],"answer":1,"explanation":"Amplitudes are in the ratio √4 : √1 = 2 : 1. I_max/I_min = (a₁ + a₂)²/(a₁ − a₂)² = (3)²/(1)² = 9 : 1. Working with intensities instead of amplitudes gives the wrong 4 : 1.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-28","question":"A light pulse passes normally through a glass slab 6 cm thick with refractive index 1.5. The time taken by the light to cross the slab is (c = 3 × 10⁸ m/s):","options":["2 × 10⁻¹⁰ s","3 × 10⁻¹⁰ s","4.5 × 10⁻¹⁰ s","1 × 10⁻¹⁰ s"],"answer":1,"explanation":"Speed in glass v = c/n = 2 × 10⁸ m/s, so t = d/v = 0.06/(2 × 10⁸) = 3 × 10⁻¹⁰ s. Equivalently, the optical path is nd = 9 cm and t = 0.09/c. Using c directly gives 2 × 10⁻¹⁰ s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-29","question":"A parallel beam of light falls on a solid glass sphere of radius 10 cm and refractive index 1.5. The beam is finally focused at a point that is:","options":["5 cm from the far surface, outside the sphere","10 cm from the far surface, outside the sphere","At the far surface of the sphere","At the centre of the sphere"],"answer":0,"explanation":"First surface (u = −∞, R = +10): 1.5/v = 0.5/10 gives v = 30 cm, i.e. 10 cm beyond the far surface, which is a virtual object for it. Second surface (u = +10, R = −10, from glass to air): 1/v − 1.5/10 = (1 − 1.5)/(−10) = 0.05, so 1/v = 0.2 and v = 5 cm outside the sphere.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-30","question":"Unpolarised light of intensity I₀ passes through three polaroids in succession. The transmission axis of the second makes 45° with the first, and that of the third makes 90° with the first. The intensity of the emerging light is:","options":["Zero","I₀/2","I₀/4","I₀/8"],"answer":3,"explanation":"The first polaroid passes I₀/2. By Malus's law the second passes (I₀/2) cos² 45° = I₀/4 and the third passes (I₀/4) cos² 45° = I₀/8. Without the middle polaroid, the crossed pair would transmit nothing.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-31","question":"When a ray of light passes obliquely from an optically denser medium into a rarer medium, it:","options":["bends away from the normal","bends towards the normal","goes on undeviated","is always totally reflected"],"answer":0,"explanation":"Light speeds up in the rarer medium, so the angle of refraction exceeds the angle of incidence and the ray bends away from the normal. Total reflection happens only beyond the critical angle.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-optics-32","question":"An equiconvex lens of glass (n = 1.5) has radii of curvature of 20 cm. Its focal length in air is:","options":["15 cm","40 cm","10 cm","20 cm"],"answer":3,"explanation":"Lens maker's formula: 1/f = (n − 1)(1/R₁ − 1/R₂) = 0.5 × (1/20 + 1/20) = 1/20, so f = 20 cm.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-optics-33","question":"An object is placed 30 cm in front of a concave mirror of focal length 20 cm. The magnification of the image is:","options":["−0.5","+2","−3","−2"],"answer":3,"explanation":"With u = −30 cm and f = −20 cm: 1/v = 1/f − 1/u = −1/20 + 1/30 = −1/60, so v = −60 cm and m = −v/u = −2 (real, inverted, enlarged).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-optics-34","question":"A coin lies at the bottom of a beaker with water (n = 4/3) to a depth of 12 cm. Viewed from directly above, the coin appears to be raised by:","options":["9 cm","16 cm","4 cm","3 cm"],"answer":3,"explanation":"Apparent depth = 12/(4/3) = 9 cm, so the apparent rise is 12 − 9 = 3 cm. 9 cm is the apparent depth, not the shift.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-optics-35","question":"A compound microscope has an objective of focal length 1 cm and an eyepiece of focal length 5 cm, with a tube length of 20 cm. In normal adjustment (final image at infinity, D = 25 cm), its magnifying power is about:","options":["500","120","25","100"],"answer":3,"explanation":"m ≈ (L/f_o)(D/f_e) = (20/1)(25/5) = 100. Using (1 + D/f_e) = 6 for the eyepiece gives 120, which applies when the final image is at the near point.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-36","question":"In Young's double-slit experiment the fringe width in air is 0.6 mm. When the whole apparatus is immersed in water (n = 4/3), the fringe width becomes:","options":["0.45 mm","0.8 mm","0.6 mm","0.3 mm"],"answer":0,"explanation":"β = λD/d, and the wavelength in water is λ/n. So β' = 0.6 × 3/4 = 0.45 mm.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-37","question":"An equiconvex lens of focal length f is cut into two identical plano-convex halves by a plane perpendicular to its principal axis. The focal length of each half is:","options":["f","2f","infinite","f/2"],"answer":1,"explanation":"Each half has one curved surface and one flat one: 1/f' = (n − 1)/R, half the original 2(n − 1)/R, so f' = 2f. Cutting along the axis instead would leave the focal length f.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-optics-38","question":"The objective of a telescope has a diameter of 1.22 m. For light of wavelength 500 nm, its limit of resolution (smallest angular separation) is:","options":["1 × 10⁻⁶ rad","5 × 10⁻⁷ rad","6.1 × 10⁻⁷ rad","2.5 × 10⁻⁷ rad"],"answer":1,"explanation":"θ = 1.22λ/D = 1.22 × 5 × 10⁻⁷/1.22 = 5 × 10⁻⁷ rad. A larger aperture gives a smaller angle, i.e. better resolution.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-optics-39","question":"An object and a screen are 90 cm apart. A convex lens placed between them gives a sharp image on the screen in two positions that are 30 cm apart. The focal length of the lens is:","options":["18 cm","15 cm","22.5 cm","20 cm"],"answer":3,"explanation":"Displacement method: f = (D² − d²)/4D = (8100 − 900)/360 = 20 cm. The two positions have u and v interchanged (30 cm and 60 cm), and 1/60 + 1/30 = 1/20 confirms it.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-40","question":"A point source lies at depth h below the surface of water (refractive index 4/3). The minimum radius of an opaque disc floating on the surface, centred above the source, that prevents any light from emerging is:","options":["h√7/3","3h/√7","3h/4","4h/3"],"answer":1,"explanation":"Only rays within the critical angle C escape: sinC = 3/4, so tanC = 3/√7. The disc must cover r = h tanC = 3h/√7.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-41","question":"How many of the following statements are correct?\n(A) Sound waves in air cannot be polarised.\n(B) At Brewster's angle, tan θ_B = n (refractive index of the reflecting medium).\n(C) In single-slit diffraction the central maximum is twice as wide as the other maxima.\n(D) The bright and dark fringes in Young's double-slit experiment are unequally spaced.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A (sound in air is longitudinal), B and C are correct. D is wrong: for small angles the fringes in YDSE are equally spaced, β = λD/d. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-optics-42","question":"Two plane mirrors are inclined at 60° to each other. An object is placed between them. The number of images formed is:","options":["3","4","6","5"],"answer":3,"explanation":"360°/60° = 6, which is even, so the number of images is 6 − 1 = 5, wherever the object is placed between the mirrors.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-optics-43","question":"An air bubble inside a glass slab (n = 1.5) appears to be 6 cm below one face when viewed normally through that face, and 4 cm below the opposite face when viewed through it. The thickness of the slab is:","options":["6.67 cm","12 cm","15 cm","10 cm"],"answer":2,"explanation":"Real depth = n × apparent depth: 1.5 × 6 = 9 cm from one face and 1.5 × 4 = 6 cm from the other, so the thickness is 15 cm. Adding the apparent depths gives 10 cm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-44","question":"An astronomical telescope has an objective of focal length 50 cm and an eyepiece of focal length 5 cm. When the final image is formed at the least distance of distinct vision (25 cm), its magnifying power is:","options":["15","8.33","12","10"],"answer":2,"explanation":"M = (f_o/f_e)(1 + f_e/D) = 10 × (1 + 5/25) = 12. 10 is the value in normal adjustment (image at infinity).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-45","question":"Assertion (A): The objective of an astronomical telescope is made with a large focal length and a large aperture.\nReason (R): A large aperture improves resolving power and light-gathering power, while a large focal length increases the magnifying power.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: M = f_o/f_e grows with f_o, and resolving power ∝ D/1.22λ grows with the aperture, which also collects more light for faint objects.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-optics-46", "question": "The focal length of a plane mirror is:", "options": ["zero", "equal to the object distance", "infinite", "25 cm"], "answer": 2, "explanation": "A plane mirror is a spherical mirror of infinite radius of curvature, so f = R/2 = ∞ and its power is zero.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-optics-47", "question": "When white light passes through a glass prism, the colour that is deviated the least is:", "options": ["red", "violet", "green", "blue"], "answer": 0, "explanation": "The refractive index of glass is smallest for red (the longest visible wavelength), so red is deviated least and violet most.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-optics-48", "question": "An object is placed 10 cm in front of a concave mirror of focal length 15 cm. The image is:", "options": ["real, inverted, 30 cm in front of the mirror, magnified 3 times", "virtual, erect, 6 cm behind the mirror, magnified 0.6 times", "real, inverted, 6 cm in front of the mirror", "virtual, erect, 30 cm behind the mirror, magnified 3 times"], "answer": 3, "explanation": "With u = −10 cm and f = −15 cm: 1/v = −1/15 + 1/10 = 1/30, so v = +30 cm (behind the mirror, virtual) and m = −v/u = +3. An object inside the focus always gives an erect, magnified, virtual image.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-optics-49", "question": "A plano-convex lens of glass (n = 1.5) has a curved surface of radius 30 cm. Its focal length is:", "options": ["30 cm", "60 cm", "15 cm", "45 cm"], "answer": 1, "explanation": "1/f = (n − 1)(1/R − 0) = 0.5/30, so f = 60 cm. 30 cm treats it as an equiconvex lens.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-optics-50", "question": "A ray of light in air strikes the surface of glass of refractive index √3 at an angle of incidence of 60°. The angle of refraction is:", "options": ["60°", "30°", "45°", "20°"], "answer": 1, "explanation": "sin r = sin 60°/√3 = (√3/2)/√3 = 1/2, so r = 30°. (Here the reflected and refracted rays are perpendicular: 60° is Brewster's angle for this glass.)", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-optics-51", "question": "A plane mirror is rotated through 10° about an axis in its plane while the incident ray is kept fixed. The reflected ray turns through:", "options": ["10°", "5°", "40°", "20°"], "answer": 3, "explanation": "Rotating the mirror by θ changes the angle of incidence by θ, and the reflected ray turns by 2θ = 20°. This is the principle of the optical lever.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-optics-52", "question": "The resolving power of a microscope can be increased by:", "options": ["using light of shorter wavelength", "using light of longer wavelength", "decreasing the numerical aperture of the objective", "using an eyepiece of longer focal length"], "answer": 0, "explanation": "The smallest resolvable separation is d = 1.22λ/(2n sin θ), so a shorter λ (or an oil-immersion objective, which raises n) improves resolution. That is why electron microscopes resolve far finer detail.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-optics-53", "question": "In Young's double-slit experiment the fringe width is β. The distance between the third bright fringe and the second dark fringe on the same side of the central maximum is:", "options": ["β", "0.5β", "1.5β", "2.5β"], "answer": 2, "explanation": "The nth bright fringe is at nβ and the nth dark fringe at (n − ½)β. So 3β − 1.5β = 1.5β. Treating the second dark fringe as being at 2.5β gives 0.5β.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-optics-54", "question": "A thin glass prism (n = 1.5) produces a deviation δ in air. When the prism is immersed in water (n = 4/3), the deviation becomes:", "options": ["δ/2", "δ", "3δ/4", "δ/4"], "answer": 3, "explanation": "δ = (n_rel − 1)A. In air n_rel − 1 = 0.5; in water n_rel = 1.5/(4/3) = 9/8, so n_rel − 1 = 1/8. The ratio is (1/8)/(1/2) = 1/4.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-55", "question": "An object is 30 cm in front of a concave mirror of focal length 20 cm and moves along the principal axis at 1 cm/s. The speed of its image at that instant is:", "options": ["2 cm/s", "4 cm/s", "1 cm/s", "0.25 cm/s"], "answer": 1, "explanation": "Here v = −60 cm and m = −2. Differentiating the mirror formula gives v_image = −(v/u)² v_object, so the image moves at m² × 1 = 4 cm/s. 2 cm/s multiplies by m instead of m².", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-56", "question": "The lower half of a convex lens is covered with black paper. The image of an object formed by the lens is:", "options": ["only the upper half of the image", "only the lower half of the image", "the complete image, but with reduced brightness", "no image at all"], "answer": 2, "explanation": "Every part of the lens forms a complete image; covering half of it only halves the light reaching the image. The image is whole but dimmer.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-optics-57", "question": "Two thin convex lenses of focal lengths 20 cm and 30 cm are placed coaxially 10 cm apart. The equivalent focal length of the combination is:", "options": ["15 cm", "12 cm", "50 cm", "24 cm"], "answer": 0, "explanation": "1/F = 1/f₁ + 1/f₂ − d/(f₁f₂) = 1/20 + 1/30 − 10/600 = (3 + 2 − 1)/60 = 4/60, so F = 15 cm. 12 cm assumes the lenses are in contact.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-58", "question": "A point object in air is 30 cm from the convex spherical surface (radius 10 cm) of a long glass rod of refractive index 1.5. The image is formed:", "options": ["30 cm inside the glass (real)", "90 cm in front of the surface (virtual)", "90 cm inside the glass (real)", "60 cm inside the glass (real)"], "answer": 2, "explanation": "n₂/v − n₁/u = (n₂ − n₁)/R: 1.5/v + 1/30 = 0.5/10, so 1.5/v = 1/20 − 1/30 = 1/60 and v = +90 cm, a real image inside the glass.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-59", "question": "The rear-view mirror of a car is convex with a radius of curvature of 2 m. A bus is 6 m behind the car. The magnification of the bus's image is:", "options": ["1/7", "1/6", "1/5", "1/3"], "answer": 0, "explanation": "f = +1 m and u = −6 m: 1/v = 1 − (−1/6) = 7/6, so v = 6/7 m behind the mirror and m = −v/u = (6/7)/6 = 1/7, an erect, diminished image.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-optics-60", "question": "How many of the following statements are correct?\n(A) The lateral magnification produced by a plane mirror is +1.\n(B) A convex mirror always forms a virtual, erect and diminished image of a real object.\n(C) A concave lens can form a real image of a real object.\n(D) The focal length of a lens depends on the colour of the light used.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and D are correct (D because n varies with wavelength, which causes chromatic aberration). C is wrong: a diverging lens always forms a virtual image of a real object. Three are correct.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-optics-61", "question": "In Young's double-slit experiment (slit separation 1 mm, screen 1 m away), light of wavelengths 600 nm and 400 nm is used together. The nearest point to the central maximum where bright fringes of both wavelengths coincide is at a distance of:", "options": ["0.6 mm", "2.4 mm", "0.4 mm", "1.2 mm"], "answer": 3, "explanation": "We need n₁ × 600 = n₂ × 400, whose smallest solution is n₁ = 2, n₂ = 3 (path difference 1200 nm). y = 1200 × 10⁻⁹ × 1/10⁻³ = 1.2 mm. 0.6 mm is only the first bright fringe of the 600 nm light.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-62", "question": "A prism has a refracting angle of 60°. The condition on its refractive index n for which no ray can emerge from the second face, whatever the angle of incidence on the first face, is:", "options": ["n > √2", "n > 2", "n > √3", "n > 1.5"], "answer": 1, "explanation": "A ray can always emerge if A ≤ 2C, where C is the critical angle; no ray emerges if A > 2C, i.e. C < 30°, so sin C = 1/n < 1/2 and n > 2. n > √2 corresponds to C < 45°, the condition for a 90° prism.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-optics-63", "question": "A biconvex glass lens (n = 1.5) has a focal length of 20 cm in air. When immersed in a liquid of refractive index 1.75, it behaves as:", "options": ["a converging lens of focal length 70 cm", "a diverging lens of focal length 70 cm", "a diverging lens of focal length 20 cm", "a plane glass plate (infinite focal length)"], "answer": 1, "explanation": "1/f = (n_rel − 1)(1/R₁ − 1/R₂). In air 0.5 × (1/R₁ − 1/R₂) = 1/20, so the bracket is 1/10. In the liquid n_rel = 1.5/1.75 = 6/7, so 1/f′ = (−1/7)(1/10) and f′ = −70 cm, a diverging lens because the surrounding medium is optically denser.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-64", "question": "A bird is 30 cm above the surface of a pond, and a fish is 20 cm below the surface, vertically below the bird (refractive index of water 4/3, near-normal viewing). The apparent distance of the bird as seen by the fish, and of the fish as seen by the bird, are respectively:", "options": ["45 cm and 60 cm", "50 cm and 50 cm", "62.5 cm and 42.5 cm", "60 cm and 45 cm"], "answer": 3, "explanation": "To the fish the bird appears at 30 × 4/3 = 40 cm above the surface: 40 + 20 = 60 cm. To the bird the fish appears at 20 × 3/4 = 15 cm below the surface: 30 + 15 = 45 cm.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-optics-65", "question": "In a double-slit experiment the slit separation is 5 times the width of each slit, so the 5th-order interference maxima fall exactly on the first minima of the single-slit diffraction pattern. The number of bright interference fringes inside the central diffraction maximum is:", "options": ["9", "10", "11", "5"], "answer": 0, "explanation": "The first diffraction minimum is at sin θ = λ/a, where the interference order is d/a = 5. Those 5th-order fringes are missing, so the orders −4 to +4 survive: 9 bright fringes. 10 or 11 wrongly count the missing 5th orders.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-optics-66", "question": "Assertion (A): The Sun looks reddish at sunrise and sunset.\nReason (R): Red light is scattered the most by the molecules of the atmosphere.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true but R is false: Rayleigh scattering ∝ 1/λ⁴, so blue is scattered most. Near the horizon sunlight crosses a long path of air that scatters away most of the blue, leaving mainly red to reach us.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-optics-67", "question": "Match the phenomenon (List I) with its cause (List II).\nList I: (P) mirage in a desert; (Q) twinkling of stars; (R) blue colour of the clear sky; (S) colours of a thin soap film.\nList II: (1) interference; (2) scattering; (3) fluctuating atmospheric refraction; (4) total internal reflection.", "options": ["P-3, Q-4, R-2, S-1", "P-4, Q-3, R-1, S-2", "P-4, Q-3, R-2, S-1", "P-2, Q-3, R-4, S-1"], "answer": 2, "explanation": "A mirage comes from total internal reflection in hot, optically rarer air near the ground; twinkling from the changing refraction of turbulent air; the blue sky from Rayleigh scattering; and soap-film colours from interference between the light reflected at the film's two surfaces.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-optics-68", "question": "A hypermetropic person's near point is 75 cm from the eye. The power of the lens needed for him to read a book held at 25 cm is about:", "options": ["−2.67 D", "+4 D", "+1.33 D", "+2.67 D"], "answer": 3, "explanation": "The lens must form a virtual image at 75 cm of an object at 25 cm: 1/f = 1/v − 1/u = −1/75 + 1/25 = 2/75, so f = 37.5 cm and P = 100/37.5 ≈ +2.67 D, a converging lens.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-optics-69", "question": "Two plane mirrors are inclined at 60° to each other. A ray that is reflected once from each mirror is deviated from its original direction by:", "options": ["120°", "240°", "60°", "180°"], "answer": 1, "explanation": "For two successive reflections from mirrors inclined at θ, the total deviation is 360° − 2θ = 240°, whatever the angle of incidence. This is equivalent to a net rotation of 2θ = 120° in the other sense.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-optics-70", "question": "The Brewster angle for light passing from air into a certain glass is 60°. The critical angle for light passing from this glass into air is:", "options": ["30°", "60°", "sin⁻¹(1/√3) ≈ 35°", "sin⁻¹(√3/2)"], "answer": 2, "explanation": "tan θ_B = n gives n = tan 60° = √3. Then sin C = 1/n = 1/√3, so C ≈ 35.3°. 30° wrongly takes C = 90° − θ_B.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-optics-71","question":"A thin glass lens (n = 1.5) has one convex surface of radius 20 cm and one concave surface of radius 40 cm, both curving the same way (a meniscus). Its focal length in air is:","options":["+80 cm (converging)","−80 cm (diverging)","+26.7 cm (converging)","+40 cm (converging)"],"answer":0,"explanation":"With both centres of curvature on the same side, R₁ = +20 cm and R₂ = +40 cm: 1/f = 0.5(1/20 − 1/40) = 1/80, so f = +80 cm and the lens converges (it is thicker at the middle). Adding the curvatures, as for a biconvex lens, gives 26.7 cm.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-optics-72","question":"Unpolarised light of intensity I₀ passes through two ideal polaroids whose transmission axes are at 60° to each other. The intensity of the emerging light is:","options":["I₀/4","I₀/8","3I₀/8","I₀/2"],"answer":1,"explanation":"The first polaroid passes I₀/2. Malus's law at the second: (I₀/2)cos²60° = (I₀/2)(1/4) = I₀/8. Forgetting the first halving gives I₀/4.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-optics-73","question":"An object is fixed in front of a plane mirror. The mirror is moved directly away from the object at 3 cm/s, keeping it parallel to itself. The image moves:","options":["at 3 cm/s away from the object","at 1.5 cm/s away from the object","at 6 cm/s away from the object","at 6 cm/s towards the object"],"answer":2,"explanation":"The image is always as far behind the mirror as the object is in front: if the mirror moves x away, the object–mirror distance grows by x and the object–image distance by 2x. So the image moves at 6 cm/s, away from the object.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-optics-74","question":"An optical fibre has a core of refractive index 1.5 and a cladding of refractive index 1.4, and is used in air. The largest angle with the fibre axis at which light can enter the end face and still be guided by total internal reflection is about:","options":["69°","21°","57°","33°"],"answer":3,"explanation":"Inside, the ray must meet the core–cladding wall at least at the critical angle C with sin C = 1.4/1.5, so the refraction angle at the entry face is r = 90° − C. Then sin θ = 1.5 sin r = √(1.5² − 1.4²) = √0.29 ≈ 0.539, so θ ≈ 33°. 69° is the critical angle itself.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-75","question":"An object moves along the principal axis towards a thin convex lens of focal length 20 cm at 2 cm/s. At the instant it is 30 cm from the lens, its image moves:","options":["at 8 cm/s away from the lens","at 8 cm/s towards the lens","at 4 cm/s away from the lens","at 2 cm/s towards the lens"],"answer":0,"explanation":"v = 60 cm, and differentiating 1/v − 1/u = 1/f gives dv/dt = (v²/u²) du/dt = (60/30)² × 2 = 8 cm/s. As the object comes closer to F, the real image runs farther out, i.e. away from the lens. Using the magnification m = 2 instead of m² gives 4 cm/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-76","question":"In a Young's double-slit set-up the source slit is 20 cm from the double slit and the screen is 1 m beyond it. If the source slit is moved 1 mm upward, perpendicular to the axis, the central bright fringe moves:","options":["5 mm upward","5 mm downward","0.2 mm downward","1 mm downward"],"answer":1,"explanation":"Moving the source by y adds a path difference yd/d′ before the slits; the central fringe moves to where Yd/D cancels it, i.e. on the opposite side, with Y = yD/d′ = 1 × 100/20 = 5 mm downward. Shifting it upward ignores which side the extra path is on.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-77","question":"A plane mirror is placed 10 cm behind a thin convex lens of focal length 20 cm, perpendicular to the axis. Where must a small object be placed in front of the lens so that the final image (after refraction, reflection and refraction again) is formed at the object itself?","options":["40 cm from the lens","30 cm from the lens","20 cm from the lens","10 cm from the lens"],"answer":2,"explanation":"If the object is at the focus, the rays leave the lens parallel, strike the plane mirror normally and retrace their path, focusing back at the object. The position of a plane mirror does not matter. 40 cm (2f) is the answer for a concave mirror at the lens, not a plane one.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-78","question":"A prism of refracting angle 60° is made of glass of refractive index 1.5. The smallest angle of incidence on the first face for which the ray can emerge from the second face is about:","options":["48.6°","41.8°","18.2°","27.9°"],"answer":3,"explanation":"At the limit, the ray meets the second face at the critical angle C = sin⁻¹(1/1.5) = 41.8°, so r₁ = 60° − 41.8° = 18.2°. Then sin i = 1.5 sin 18.2° ≈ 0.468 and i ≈ 27.9°. Smaller angles of incidence give total internal reflection at the second face. 18.2° is the refraction angle, not the incidence angle.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-79","question":"A small fish is at the centre of a spherical glass bowl of radius 15 cm filled with water (n = 4/3); the thin glass wall can be ignored. Seen from outside, the fish appears:","options":["at the centre, magnified 4/3 times","at the centre, with its real size","11.25 cm from the near wall, unmagnified","20 cm from the near wall, magnified 4/3 times"],"answer":0,"explanation":"Rays from the centre meet the surface normally, so the image is at the centre: n₂/v − n₁/u = (n₂ − n₁)/R with n₁ = 4/3, n₂ = 1, u = R = −15 cm gives v = −15 cm. The magnification is m = n₁v/(n₂u) = 4/3. 11.25 cm wrongly applies the plane-surface apparent-depth formula.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-80","question":"The headlights of a car are 1.2 m apart. Taking the pupil diameter of the eye as 3 mm and the wavelength of light as 500 nm, the greatest distance at which the eye can just resolve the two headlights (diffraction limit only) is about:","options":["2.4 km","5.9 km","7.2 km","12 km"],"answer":1,"explanation":"The limit of resolution is θ = 1.22λ/D = 1.22 × 5 × 10⁻⁷/(3 × 10⁻³) ≈ 2.03 × 10⁻⁴ rad. Distance = 1.2/θ ≈ 5.9 × 10³ m. Dropping the factor 1.22 gives 7.2 km.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-optics-81","question":"A convex lens of focal length 20 cm is cut into two halves along a diameter, and the halves are separated symmetrically by 1 mm (a split lens), the gap being blocked. A point source is placed on the original axis 30 cm from the lens. The two real images it produces are separated by:","options":["1 mm","2 mm","3 mm","6 mm"],"answer":2,"explanation":"Each half acts as a lens whose optical centre is 0.5 mm off the axis. With v = 60 cm and m = −2, the image formed by a lens centred at height h lies at h(1 − m) = 3h. The images are at ±1.5 mm, i.e. 3 mm apart (= d(1 + v/u)). Answering 2 mm uses |m| × d.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-82","question":"The curved surface (radius of curvature 20 cm) of a thin plano-convex glass lens (n = 1.5) is silvered, and light is incident on the plane face. The system behaves like a:","options":["convex mirror of focal length 6.67 cm","concave mirror of focal length 20 cm","concave mirror of focal length 10 cm","concave mirror of focal length 6.67 cm"],"answer":3,"explanation":"Light passes through the lens, reflects at the silvered curved surface and passes through the lens again: P = 2P_lens + P_mirror = 2(0.5/20) + 2/20 = 0.15 cm⁻¹, so F = 6.67 cm (= R/2n), converging. 20 cm is the result when the plane face is the silvered one.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-83","question":"In a double-slit experiment the two slits send light of intensities I and 4I to the screen. At a point where the path difference between the two waves is λ/3, the resultant intensity is:","options":["3I","7I","5I","I"],"answer":0,"explanation":"Phase difference = 2π/3. I_net = I₁ + I₂ + 2√(I₁I₂) cos(2π/3) = I + 4I + 2(2I)(−1/2) = 3I. Taking cos 60° instead (phase π/3) gives 7I; ignoring interference gives 5I.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-84","question":"A glass hemisphere (n = 1.5) of radius R rests with its flat face on a sheet of paper. A small dot on the paper lies directly under the centre of the flat face. Viewed from directly above, along the axis, the dot appears:","options":["at a depth R/1.5 below the top of the hemisphere","at its actual position","raised by R/3","at a depth 1.5R below the top of the hemisphere"],"answer":1,"explanation":"The dot is at the centre of the spherical surface, so every ray from it travels along a radius and meets the curved surface normally, leaving undeviated. The image therefore coincides with the dot. Applying the plane-slab formula (apparent depth R/n) is the trap: the top surface is not plane.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-85","question":"A thin convex lens of focal length 20 cm and a concave mirror of focal length 10 cm face each other on a common axis, 80 cm apart. A small object stands 30 cm in front of the lens, on the side away from the mirror. After refraction through the lens, reflection at the mirror and refraction back through the lens, the final image is:","options":["30 cm from the lens on the object side, erect and half the size","at the object's position, erect and of the same size","at the object's position, inverted and of the same size","60 cm from the lens on the mirror side, inverted and twice as large"],"answer":2,"explanation":"Lens: v = 60 cm, m₁ = −2, so the image is 20 cm from the mirror, at its centre of curvature: m₂ = −1, image formed at the same place. Back through the lens: u = 60 cm gives v = 30 cm, m₃ = −1/2. Final image is at the object, total m = (−2)(−1)(−1/2) = −1: inverted, same size.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-86","question":"Unpolarised light is reflected from a glass surface at Brewster's angle. The reflected beam then passes through an ideal polaroid whose transmission axis makes 30° with the plane of incidence. The fraction of the reflected intensity that gets through is:","options":["1/8","3/4","1/2","1/4"],"answer":3,"explanation":"At Brewster's angle the reflected light is completely polarised with E perpendicular to the plane of incidence. The polaroid axis is then at 90° − 30° = 60° to E, so Malus's law gives cos²60° = 1/4. Measuring the angle from the plane of incidence directly gives 3/4; halving as for unpolarised light gives 1/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-87","question":"How many of the following statements are correct?\n(A) In single-slit diffraction the angular width of the central maximum is 2λ/a, a being the slit width.\n(B) Making the slit narrower makes the central diffraction maximum wider.\n(C) In Young's experiment, doubling both the slit separation and the slit-to-screen distance halves the fringe width.\n(D) Light from two separate sodium lamps can produce a steady interference pattern on a screen.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and B are correct (first minima at sin θ = ±λ/a). C is wrong: β = λD/d is unchanged when D and d are both doubled. D is wrong: independent lamps are not coherent, as their relative phase changes randomly every ~10⁻⁸ s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-88","question":"Assertion (A): In Young's double-slit experiment, moving the screen farther from the slits increases the fringe width but leaves the angular fringe width unchanged.\nReason (R): The fringe width in Young's experiment does not depend on the wavelength of the light used.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: β = λD/d grows with D, but the angle one fringe subtends at the slits, β/D = λ/d, involves only λ and d. R is false: β = λD/d is directly proportional to λ, which is why red fringes are wider than blue ones.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-89","question":"For a thin convex lens of focal length 20 cm, match the object distance (List I) with the magnification produced (List II).\nList I: (P) 10 cm; (Q) 30 cm; (R) 40 cm; (S) 60 cm.\nList II: (1) −1; (2) +2; (3) −1/2; (4) −2.","options":["P-2, Q-4, R-1, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-3, S-1","P-2, Q-1, R-4, S-3"],"answer":0,"explanation":"Using 1/v − 1/u = 1/f and m = v/u: u = −10 gives v = −20, m = +2 (virtual, erect); u = −30 gives v = 60, m = −2; u = −40 gives v = 40, m = −1; u = −60 gives v = 30, m = −1/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-90","question":"A prism of refractive index √3 is found to have its angle of minimum deviation equal to its refracting angle A. The value of A is:","options":["30°","60°","45°","90°"],"answer":1,"explanation":"With D_m = A, n = sin((A + D_m)/2)/sin(A/2) = sin A/sin(A/2) = 2 cos(A/2). So cos(A/2) = √3/2, A/2 = 30° and A = 60°. Then D_m = 60° as well; A = 90° would need n = √2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-91","question":"White light (400 nm to 700 nm) is used in a Young's double-slit experiment. At a point on the screen where the path difference between the two waves is 2.0 μm, the wavelengths that are completely missing (interfere destructively) are:","options":["444 nm, 500 nm and 571 nm","400 nm, 500 nm and 667 nm","444 nm and 571 nm","500 nm only"],"answer":2,"explanation":"Destructive interference needs 2000 nm = (m + 1/2)λ: m = 3 gives 571 nm and m = 4 gives 444 nm (m = 2 gives 800 nm, m = 5 gives 364 nm, outside the range). 400, 500 and 667 nm (= 2000/m) are the wavelengths that are reinforced there.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-92","question":"A ray of light strikes a parallel-sided glass slab 6 cm thick (n = √3) at an angle of incidence of 60°. The perpendicular distance between the incident ray and the emergent ray (the lateral shift) is:","options":["√3 cm ≈ 1.73 cm","3 cm","6 cm","2√3 cm ≈ 3.46 cm"],"answer":3,"explanation":"sin r = sin 60°/√3 = 1/2, so r = 30°. Lateral shift = t sin(i − r)/cos r = 6 × sin 30°/cos 30° = 6 × 0.5/0.866 = 2√3 ≈ 3.46 cm. Using t sin(i − r) without dividing by cos r gives 3 cm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-93","question":"A solid glass sphere (n = 1.5) of radius 10 cm contains a small air bubble 5 cm from its centre. Viewed from the side of the sphere nearest the bubble, along the diameter through it, the bubble appears to be at a distance below the surface of:","options":["4 cm","3.33 cm","5 cm","6 cm"],"answer":0,"explanation":"The bubble is 5 cm inside the near surface. For refraction from glass into air: n₂/v − n₁/u = (n₂ − n₁)/R with n₁ = 1.5, n₂ = 1, u = −5 cm, R = −10 cm: 1/v + 0.3 = 0.05, so v = −4 cm. The plane-surface formula 5/1.5 = 3.33 cm ignores the curvature.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-94","question":"Two thin lenses in contact form an achromatic combination of focal length +40 cm. The dispersive powers of their materials are 0.02 and 0.04. The focal lengths of the lenses made of these materials are respectively:","options":["+40 cm and −80 cm","+20 cm and −40 cm","−20 cm and +40 cm","+13.3 cm and +26.7 cm"],"answer":1,"explanation":"Achromatism: ω₁/f₁ + ω₂/f₂ = 0 and 1/f₁ + 1/f₂ = 1/40. With ω₂ = 2ω₁, 1/f₂ = −1/(2f₁), so 1/(2f₁) = 1/40: f₁ = +20 cm (crown, converging) and f₂ = −40 cm. The converging lens must be the one with the smaller dispersive power.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-95","question":"Two coherent point sources emitting in phase, with wavelength λ, are 3λ apart. A detector is moved around a very large circle in the plane containing both sources, centred midway between them. The number of points on the circle at which the intensity is maximum is:","options":["6","7","12","14"],"answer":2,"explanation":"Far away, the path difference is 3λ cos θ, and maxima need 3 cos θ = m with m = 0, ±1, ±2, ±3. Each of m = 0, ±1, ±2 occurs at two angles (10 points), while m = ±3 occurs only on the line of the sources (θ = 0, π): 2 more points, 12 in all. Counting each order twice gives 14.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-optics-96","question":"For a real object placed anywhere in front of a convex mirror, the image is always:","options":["real or virtual depending on the object distance","real, inverted and diminished","virtual, erect and magnified","virtual, erect and diminished"],"answer":3,"explanation":"A convex mirror diverges the reflected rays, which appear to come from a point between the pole and the focus behind the mirror. The image is therefore always virtual, upright and smaller than the object — the reason it is used as a rear-view mirror.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-optics-97","question":"Light of a single colour passes from air into glass. Which property of the light remains unchanged?","options":["speed","wavelength","frequency","direction, for every angle of incidence"],"answer":2,"explanation":"The frequency is set by the source and cannot change at a boundary. The speed falls to c/n, so the wavelength also falls to λ/n; the direction changes unless the incidence is normal.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-optics-98","question":"An equiconvex glass lens (n = 1.5) with both radii of curvature 20 cm has its back surface silvered. It behaves like a concave mirror of focal length:","options":["10 cm","5 cm","20 cm","6.7 cm"],"answer":1,"explanation":"Light passes through the lens, reflects from the silvered surface (a mirror of focal length R/2 = 10 cm) and passes through the lens again. The power of the system is 2P_lens + P_mirror = 2/20 + 1/10 = 1/5 cm⁻¹, so F = 5 cm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-99","question":"A prism of refracting angle 60° has refractive index √2. For a ray to emerge from the second face (rather than being totally internally reflected there), its angle of incidence on the first face must be at least about:","options":["21.5°","15°","30°","45°"],"answer":0,"explanation":"The critical angle is 45°, so at the second face r₂ ≤ 45°. Since r₁ + r₂ = 60°, r₁ ≥ 15°. Then sin i ≥ √2 sin 15° ≈ 0.366, giving i ≥ 21.5°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-100","question":"A thin crown-glass prism of angle 6° (n = 1.5) is combined with a thin flint-glass prism (n = 1.6), placed with its refracting angle reversed, so that a ray of the mean colour passes with no net deviation. The angle of the flint prism is:","options":["5°","7.2°","6°","4°"],"answer":0,"explanation":"Thin-prism deviation is (n − 1)A. For zero net deviation: 0.5 × 6° = 0.6 × A₂, so A₂ = 5°. Because the dispersive powers differ, the combination still disperses light (a direct-vision prism).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-101","question":"An object is placed 10 cm beyond the first focal point of a thin convex lens of focal length 20 cm (i.e. 30 cm from the lens). Using Newton's form of the lens equation, the image is formed at a distance from the lens of:","options":["12 cm","40 cm","30 cm","60 cm"],"answer":3,"explanation":"Newton's formula x₁x₂ = f² measures distances from the focal points. x₂ = 400/10 = 40 cm beyond the second focal point, i.e. 20 + 40 = 60 cm from the lens (agreeing with 1/v − 1/u = 1/f).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-102","question":"In a Young's double-slit set-up, the plane wavefront falling on the slits is tilted so that it arrives at an angle θ to the normal of the slit plane, instead of normally. As a result, the central (zero order) bright fringe:","options":["becomes dark","stays on the axis of symmetry","moves to the angle θ on the opposite side of the axis, along the original direction of the light","moves to an angle 2θ"],"answer":2,"explanation":"An extra path difference d sin θ now exists before the slits. Zero total path difference occurs where the path difference after the slits cancels it, i.e. at angle θ on the other side: the central fringe lies along the undeviated direction of the incident light. The fringe width is unchanged.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-103","question":"In Young's double-slit experiment with equal slit intensities, the maximum intensity on the screen is I_max. At a point where the path difference between the two waves is λ/3, the intensity is:","options":["I_max/2","I_max/4","3I_max/4","zero"],"answer":1,"explanation":"Phase difference φ = (2π/λ)(λ/3) = 2π/3. I = I_max cos²(φ/2) = I_max cos²60° = I_max/4.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-104","question":"In a Young's double-slit experiment (slit separation 1 mm, screen 1 m away) the slits are illuminated simultaneously with wavelengths 600 nm and 400 nm. The nearest point to the central maximum where bright fringes of both wavelengths coincide is at a distance of:","options":["0.6 mm","1.2 mm","2.4 mm","0.4 mm"],"answer":1,"explanation":"Bright fringes coincide when n₁λ₁ = n₂λ₂: 2 × 600 = 3 × 400 = 1200 nm is the smallest common path difference. y = (1200 × 10⁻⁹ × 1)/10⁻³ = 1.2 × 10⁻³ m = 1.2 mm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-105","question":"A thin coating of magnesium fluoride (n = 1.38) is applied to a glass lens (n = 1.5) to reduce reflection of light of wavelength 552 nm (in air) at normal incidence. The minimum thickness of the coating is:","options":["100 nm","200 nm","50 nm","138 nm"],"answer":0,"explanation":"Both reflections (air–coating and coating–glass) occur at a denser medium, so both suffer a phase change of π and cancel out. Destructive interference then needs 2nt = λ/2, so t = λ/(4n) = 552/(4 × 1.38) = 100 nm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-106","question":"Light of wavelength 500 nm passes through a slit of width 1 mm. The distance from the slit up to which ray optics remains a good approximation (the Fresnel distance) is about:","options":["200 m","2 mm","20 cm","2 m"],"answer":3,"explanation":"Diffraction spreading over a distance z is about zλ/a; it becomes comparable to the slit width a when z ≈ a²/λ = (10⁻³)²/(5 × 10⁻⁷) = 2 m. Beyond this, the beam's spreading by diffraction is significant.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-107","question":"A Galilean telescope has an objective of focal length 50 cm and a diverging eyepiece of focal length 5 cm. In normal adjustment (final image at infinity) the length of the tube is:","options":["50 cm","55 cm","45 cm","10 cm"],"answer":2,"explanation":"For the image of a distant object to be thrown to infinity, the focal points of the two lenses must coincide. With a concave eyepiece, it sits a distance f_e inside the objective's focal point, so L = f_o − |f_e| = 45 cm, giving an erect image of magnification 10.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-108","question":"An object is 20 cm in front of a glass slab 6 cm thick (n = 1.5) whose back face is silvered. Viewed nearly normally from the front, the brightest image appears to be located behind the front face at a distance of:","options":["26 cm","32 cm","28 cm","24 cm"],"answer":2,"explanation":"Seen through the glass, the silvered back face appears to be at 6/1.5 = 4 cm behind the front face. The object is 20 + 4 = 24 cm from this apparent mirror, so its image is 24 cm behind it, i.e. 28 cm behind the front face.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-109","question":"With a convex lens of focal length 15 cm, the smallest possible distance between a real object and its real image is:","options":["30 cm","60 cm","45 cm","15 cm"],"answer":1,"explanation":"For a real image, D = u + v with 1/u + 1/v = 1/f (magnitudes). D is least when u = v = 2f, giving D_min = 4f = 60 cm. For D < 4f no real image can be formed on a screen.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-110","question":"A short-sighted person cannot see clearly beyond 2 m. The power of the lens needed to correct this defect for distant vision is:","options":["−0.5 D","+0.5 D","−2 D","+2 D"],"answer":0,"explanation":"The lens must form a virtual image of a distant object at the far point: 1/v − 1/u = 1/f with u = −∞ and v = −2 m, so f = −2 m and P = −0.5 D (diverging).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-111","question":"A short object of length 1 mm lies along the principal axis of a concave mirror of focal length 20 cm, its centre 30 cm from the mirror. The length of its image is about:","options":["8 mm","2 mm","1 mm","4 mm"],"answer":3,"explanation":"At u = −30 cm, v = −60 cm and the lateral magnification is m = −v/u = −2. For a short object along the axis, the longitudinal magnification is −m² = −4, so the image is about 4 mm long (and reversed in direction).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-112","question":"The Sun subtends an angle of about 0.0093 rad at the Earth. A concave mirror of focal length 1 m forms an image of the Sun. The diameter of the image is about:","options":["0.93 mm","4.7 mm","18.6 mm","9.3 mm"],"answer":3,"explanation":"The Sun is effectively at infinity, so its image forms in the focal plane with diameter fθ = 1 m × 0.0093 = 9.3 mm.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-113","question":"In a Young's double-slit experiment with slit separation 1 mm, moving the screen 50 cm farther from the slits increases the fringe width by 0.3 mm. The wavelength of the light is:","options":["500 nm","300 nm","600 nm","150 nm"],"answer":2,"explanation":"β = λD/d, so Δβ = λΔD/d. λ = dΔβ/ΔD = (10⁻³ × 3 × 10⁻⁴)/0.5 = 6 × 10⁻⁷ m = 600 nm. Measuring the change removes the need to know D precisely.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-114","question":"In Lloyd's mirror arrangement, light from a slit interferes with its own reflection from a plane glass surface at grazing incidence. At the point where the direct and reflected paths are equal (the edge of the pattern at the mirror), one observes:","options":["a bright fringe, since the path difference is zero","a dark fringe, because reflection from the denser medium adds a phase change of π","no fringe, as the sources are incoherent","a bright fringe of double width"],"answer":1,"explanation":"The reflected wave undergoes a phase change of π (equivalent to λ/2) at the glass. With zero geometrical path difference the waves therefore cancel, so the zero-order fringe is dark — evidence for the phase change on reflection.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-115","question":"Two identical sodium lamps are placed side by side to illuminate a screen. No interference fringes are seen because:","options":["the two lamps are not coherent: their relative phase changes randomly millions of times per second","the lamps emit different wavelengths","light waves cannot overlap","the intensities are equal"],"answer":0,"explanation":"Each lamp emits from very many atoms independently, so the phase difference between the two lamps fluctuates randomly on timescales of about 10⁻⁸ s. The fringe pattern shifts too rapidly to be seen, and the intensities simply add.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-116","question":"A pulse of light passes normally through 3 cm of glass (n = 1.5) followed by 4 cm of water (n = 4/3). The time it takes to cross both layers is about:","options":["3.3 × 10⁻¹⁰ s","2.3 × 10⁻¹⁰ s","1.6 × 10⁻¹⁰ s","4.4 × 10⁻¹⁰ s"],"answer":0,"explanation":"Time = (optical path)/c = (1.5 × 3 + (4/3) × 4) cm/c = (4.5 + 5.33) cm/(3 × 10¹⁰ cm/s) ≈ 3.3 × 10⁻¹⁰ s. (Ignoring the refractive indices would give 2.3 × 10⁻¹⁰ s.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-117","question":"A thin lens separates air (n = 1) on one side from water (n = 4/3) on the other, like the lens of a fish's eye in an aquarium wall. Its two focal lengths, measured from the lens on the air side and on the water side, are:","options":["both infinite","equal, as for any thin lens","different, in the ratio 4/3 : 1","different, in the ratio 1 : 4/3 (air side : water side)"],"answer":3,"explanation":"For any refracting system, the focal lengths on the two sides are proportional to the refractive indices of those media: f_water/f_air = n_water/n_air = 4/3. They are equal only when the same medium is on both sides.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-118","question":"A convex lens forms a sharp image of an object on a screen. A glass slab 3 cm thick (n = 1.5) is then placed between the lens and the screen, with its faces perpendicular to the axis. To get a sharp image again, the screen must be moved:","options":["2 cm away from the lens","1 cm towards the lens","1 cm away from the lens","1.5 cm away from the lens"],"answer":2,"explanation":"A slab shifts the point of convergence of a converging beam away from the lens by t(1 − 1/n) = 3 × (1 − 2/3) = 1 cm. The screen must be moved back by 1 cm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-119","question":"A ray of light strikes a plane mirror with an angle of incidence of 30°. The angle through which the ray is deviated by the reflection is:","options":["60°","120°","30°","150°"],"answer":1,"explanation":"The deviation is 180° − 2i = 180° − 60° = 120°. (At normal incidence the ray is turned back through 180°.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-120","question":"A concave mirror of focal length 15 cm forms an erect image three times the size of the object. The distance of the object from the mirror is:","options":["20 cm","10 cm","5 cm","45 cm"],"answer":1,"explanation":"An erect image from a concave mirror is virtual, with the object inside the focus. m = f/(f − u) = 3 with f = −15 cm gives f − u = −5, so u = −10 cm: the object is 10 cm in front of the mirror (the image is 30 cm behind it).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-121","question":"A coin at the bottom of a tank of a transparent liquid appears, when viewed from directly above, to be at three-quarters of its actual depth. The critical angle for light passing from this liquid into air is about:","options":["48.6°","41.8°","36.9°","53.1°"],"answer":0,"explanation":"Apparent depth = real depth/n, so n = 4/3. sin C = 1/n = 3/4, giving C ≈ 48.6°.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-122","question":"A concave mirror of focal length 20 cm is immersed in water (n = 4/3). Its focal length in water is:","options":["infinite","26.7 cm","15 cm","20 cm, unchanged"],"answer":3,"explanation":"The law of reflection does not involve the refractive index, so the focal length of a mirror, R/2, is the same in any medium. Only the focal length of a lens changes on immersion.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-123","question":"A thick plane glass mirror silvered at the back forms several images of a candle placed in front of it. The brightest of these images is:","options":["the last one, farthest behind the mirror","the first one, formed by the front glass surface","the second one, formed by reflection at the silvered back surface","all are equally bright"],"answer":2,"explanation":"Only about 4% of the light reflects at the front glass surface, giving a faint first image. Most light enters the glass and reflects from the silvering, producing the brightest (second) image; later images, after repeated internal reflections, are progressively fainter.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-124","question":"The resolving limit of a normal eye is about 1 minute of arc. The smallest separation between two points that the eye can distinguish when they are at the near point (25 cm) is about:","options":["0.007 mm","0.7 mm","0.07 mm","0.25 mm"],"answer":2,"explanation":"1′ = (1/60)° = 2.9 × 10⁻⁴ rad. Separation = 0.25 m × 2.9 × 10⁻⁴ ≈ 7.3 × 10⁻⁵ m ≈ 0.07 mm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-optics-125","question":"The critical angle for light passing from a certain glass into air is 45°. The Brewster angle (polarising angle) for light passing from air into this glass is about:","options":["45°","54.7°","35.3°","60°"],"answer":1,"explanation":"sin C = 1/n gives n = √2. Brewster's law tan θ_B = n gives θ_B = tan⁻¹(√2) ≈ 54.7°. Note that θ_B always exceeds 45° for n > 1 while C is less than 90°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-126","question":"A small object is embedded at the centre of a solid glass sphere (n = 1.5). Viewed from outside, its image appears:","options":["at the centre, magnified 1.5 times","at the centre, with no magnification","at the surface nearest the viewer","at the centre, diminished to 2/3 of its size"],"answer":0,"explanation":"Rays from the centre meet the surface normally and pass undeviated, so the image is at the centre (also from the refraction formula, v = −R). The lateral magnification is m = n₁v/(n₂u) = 1.5 × (−R)/(1 × (−R)) = 1.5.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-127","question":"Two flat glass plates touch along one edge and are separated by a thin wire at the other, forming a thin air wedge of angle 1 × 10⁻⁴ rad. Viewed by reflected light of wavelength 600 nm at normal incidence, the spacing between successive dark fringes is:","options":["0.3 mm","6 mm","1.5 mm","3 mm"],"answer":3,"explanation":"Successive fringes correspond to air thickness differences of λ/2 (the path difference is twice the thickness). On a wedge the thickness is xθ, so the spacing is λ/(2θ) = 6 × 10⁻⁷/(2 × 10⁻⁴) = 3 × 10⁻³ m = 3 mm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-optics-128","question":"Sunlight scattered by the clear sky is observed through a polaroid, looking in a direction at 90° to the Sun's rays. As the polaroid is rotated, the brightness:","options":["varies only because of the polaroid's colour","stays constant, because skylight is unpolarised","goes to zero at every angle","varies strongly, because light scattered through 90° is highly polarised"],"answer":3,"explanation":"Air molecules oscillate perpendicular to the incident beam. Light scattered at 90° can only come from oscillations perpendicular to both the beam and the line of sight, so it is (almost) plane-polarised, and its brightness through a polaroid varies strongly on rotation.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-optics-129","question":"A concave mirror of focal length 20 cm is placed with its face upward and a thin layer of water (n = 4/3) is poured into it. The combination now behaves like a concave mirror of focal length:","options":["26.7 cm","20 cm","15 cm","10 cm"],"answer":2,"explanation":"The water forms a thin plano-convex lens in contact with the mirror; light passes through it twice. Power = P_mirror + 2P_water lens = 2/R + 2(n − 1)/R = 2n/R, so f = R/(2n) = f_mirror/n = 20/(4/3) = 15 cm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
